//! M1a acceptance 3: decode_instr_account round-trips live-captured mainnet
//! bytes; decoded WSOL/USDC (instr 0) spot TOB matches what the kit decodes
//! from the SAME bytes (fixtures generated by tests/fixtures/*.cjs).

use nautilus_deriverse::common::consts::PROGRAM_VERSION;
use nautilus_deriverse::decode::instr::decode_instr_account;

#[test]
fn live_fixture_matches_kit_decode() {
    let bytes = include_bytes!("fixtures/instr0_mainnet.bin");
    let kit: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/instr0_kit_decode.json")).unwrap();
    let snap = decode_instr_account(bytes, 0, PROGRAM_VERSION).expect("decode");

    // Header cross-fields.
    let h = &kit["header"];
    assert_eq!(
        snap.header.asset_token_decs_count,
        h["asset_token_decs_count"].as_u64().unwrap() as u32
    );
    assert_eq!(
        snap.header.crncy_token_decs_count,
        h["crncy_token_decs_count"].as_u64().unwrap() as u32
    );

    // Full ladder RAW equality (stronger than float compare).
    for (side, ladder) in [
        ("spot_bids", &snap.spot_bids),
        ("spot_asks", &snap.spot_asks),
    ] {
        let want = kit[side].as_array().unwrap();
        assert_eq!(ladder.len, want.len(), "{side} depth");
        for (i, level) in want.iter().enumerate() {
            assert_eq!(
                ladder.levels[i].px,
                level["px_raw"].as_i64().unwrap(),
                "{side}[{i}].px"
            );
            assert_eq!(
                ladder.levels[i].qty,
                level["qty_raw"].as_i64().unwrap(),
                "{side}[{i}].qty"
            );
        }
    }

    // Scaled TOB agreement (the values the kit UI would show).
    let bid = snap.spot_bids.top().unwrap();
    let ask = snap.spot_asks.top().unwrap();
    let asset_dec = 10f64.powi(snap.header.asset_token_decs_count as i32);
    let close = |a: f64, b: f64| (a - b).abs() < 1e-9;
    assert!(close(
        bid.px as f64 / 1e9,
        kit["scaled_tob"]["bid_px"].as_f64().unwrap()
    ));
    assert!(close(
        ask.px as f64 / 1e9,
        kit["scaled_tob"]["ask_px"].as_f64().unwrap()
    ));
    assert!(close(
        bid.qty as f64 / asset_dec,
        kit["scaled_tob"]["bid_qty"].as_f64().unwrap()
    ));
    assert!(close(
        ask.qty as f64 / asset_dec,
        kit["scaled_tob"]["ask_qty"].as_f64().unwrap()
    ));

    // Header best_bid/best_ask are cross-checks of ladder level 0 (§1.3).
    assert_eq!(bid.px, h["best_bid_raw"].as_i64().unwrap());
    assert_eq!(ask.px, h["best_ask_raw"].as_i64().unwrap());
}
